/**
 * Frozen-wire parity tests: canonical JSON, envelope identity, the shared
 * enqueue Lua, and the journal format/recovery contract. The vectors were
 * generated by CPython (`json.dumps`, `hmac`, `zlib.crc32`) — drift here is
 * a cross-language contract failure, not a judgment call.
 *
 * Run: node --test wire.test.mjs
 */
import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { createHash } from 'node:crypto';
import { mkdtempSync, rmSync, writeFileSync, appendFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

import { canonicalJson } from './canon.js';
import {
  buildEnvelope, canonicalDigest, canonicalSourceKey, eventId, validateTraceparent,
} from './envelope.js';
import { Journal, JournalError } from './journal.js';
import {
  DEDUPE_PREFIX, ENQUEUE_LUA, ENQUEUE_LUA_SHA1, StreamProducer, dedupeKey, sourceKey, streamName,
} from './queue.js';
import { requestHash } from './store.js';

// -- canonical JSON (Python json.dumps parity) --------------------------------

test('canonicalJson matches Python sort_keys+separators+ensure_ascii', () => {
  // Vector: python3 json.dumps({...}, sort_keys=True, separators=(",",":"))
  assert.equal(
    canonicalJson({
      emoji: '👍', remove: false,
      target: { id: '152099@g.us', kind: 'group' },
      to_author: '+85290000100', to_message_id: '3EB0F1', to_timestamp: 1730300000000,
    }),
    '{"emoji":"\\ud83d\\udc4d","remove":false,"target":{"id":"152099@g.us","kind":"group"},'
    + '"to_author":"+85290000100","to_message_id":"3EB0F1","to_timestamp":1730300000000}',
  );
  assert.equal(
    canonicalJson({ text: '你好 héllo 👍', n: 5, f: 1.5, nil: null, arr: [1, 'x'], b: true }),
    '{"arr":[1,"x"],"b":true,"f":1.5,"n":5,"nil":null,"text":"\\u4f60\\u597d h\\u00e9llo \\ud83d\\udc4d"}',
  );
});

test('requestHash matches the Python bridge_store digest', () => {
  // Vector: hashlib.sha256(canonical_json.encode()).hexdigest()
  const req = {
    emoji: '👍', remove: false,
    target: { id: '152099@g.us', kind: 'group' },
    to_author: '+85290000100', to_message_id: '3EB0F1', to_timestamp: 1730300000000,
  };
  assert.equal(
    requestHash(req),
    '0094a6fb5dcc9291fef406d3cabf19e12ce66d7859dbd18983dddd5b3207b659',
  );
});

test('canonicalJson refuses values Python could not hash identically', () => {
  assert.throws(() => canonicalJson({ n: 2 ** 60 }), /safe range/);
  assert.throws(() => canonicalJson({ n: NaN }), /non-finite/);
  assert.throws(() => canonicalJson({ f: () => {} }), /unserializable/);
});

// -- source identity ------------------------------------------------------------

const KEY = Buffer.alloc(32, 0xa1);
const SK = 'whatsapp\x1facct-1\x1f152099000000000000@g.us\x1fmessage\x1fm:3EB0F1:+85290000100';

test('canonicalSourceKey joins U+001F and validates kinds/parts', () => {
  assert.equal(
    canonicalSourceKey({
      platform: 'whatsapp', accountKey: 'acct-1',
      conversationId: '152099000000000000@g.us', kind: 'message',
      upstream: 'm:3EB0F1:+85290000100',
    }),
    SK,
  );
  assert.throws(() => canonicalSourceKey({
    platform: 'whatsapp', accountKey: 'a', conversationId: 'c', kind: 'nope', upstream: 'u',
  }), /unknown bridge kind/);
  assert.throws(() => canonicalSourceKey({
    platform: 'whatsapp', accountKey: 'a', conversationId: 'c', kind: 'message', upstream: 'x\x1fy',
  }), /separator-free/);
});

test('event_id and canonical_digest match the generated vectors', () => {
  // Vectors: hmac.new(key, sk, sha256).hexdigest() / sha256(sk).hexdigest()
  assert.equal(
    eventId(SK, KEY, 2),
    'v2:3f7097256a174991eb2a6e9449590d80b38c653cff1c5e43b6385bf4760bcf72',
  );
  assert.equal(
    canonicalDigest(SK),
    'c1b63d308396a11f9c876a807d3a154127bc3e78cee43247bb08e63baaa0bd9f',
  );
  // A key rotation mints a NEW ALIAS of the same source — digests agree.
  assert.equal(canonicalDigest(SK), canonicalDigest(SK));
  assert.notEqual(eventId(SK, KEY, 2), eventId(SK, KEY, 3));
});

test('traceparent validation accepts spec shapes only', () => {
  assert.equal(validateTraceparent('00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01'), true);
  assert.equal(validateTraceparent('ff-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01'), false);
  assert.equal(validateTraceparent('00-short-00f067aa0ba902b7-01'), false);
  assert.equal(validateTraceparent(42), false);
});

test('buildEnvelope emits every required field with clean trace', () => {
  const env = buildEnvelope({
    platform: 'whatsapp', accountKey: 'acct-1', kind: 'message',
    upstream: 'm:3EB0F1:+85290000100',
    conversationId: '152099000000000000@g.us', conversationType: 'group',
    senderId: '+85290000100', senderName: 'Someone',
    sentMs: 1730300000000, receivedMs: 1730300000120, queuedMs: 1730300000125,
    timeQuality: 'upstream', message: { body: 'hi' },
    attachments: [{ key: 'abc', media_type: 'image/png', file_name: null, size: 3 }],
    trace: { traceparent: '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01',
      tracestate: 'x=1', bogus: 'dropped' },
    receipt: null, admissionRev: 3, correlationKey: KEY, keyVersion: 1,
  });
  for (const f of ['v', 'platform', 'account_key', 'kind', 'source_key', 'event_id',
    'conversation_id', 'conversation_type', 'sender_id', 'sender_name', 'sent_ms',
    'received_ms', 'queued_ms', 'time_quality', 'message', 'attachments', 'trace',
    'receipt', 'admission_rev']) {
    assert.ok(f in env, `missing ${f}`);
  }
  assert.equal(env.v, 1);
  assert.equal(env.source_key, SK);
  assert.equal(env.event_id, eventId(SK, KEY, 1));
  assert.deepEqual(Object.keys(env.trace).sort(), ['traceparent', 'tracestate']);
});

// -- queue contract ------------------------------------------------------------

test('the enqueue Lua is byte-identical to the frozen contract', () => {
  // sha1 of the script literal — the frozen nora-bridge-wire v1 pin; the
  // canonical literal lives in nora/platform/bridge/queue.py (ENQUEUE_LUA)
  // and every bridge duplicates it verbatim so drift fails this parity.
  assert.equal(ENQUEUE_LUA_SHA1, '1f85b82d28739797b95784c0b7c3a118007ecadd');
  assert.match(ENQUEUE_LUA, /XADD', KEYS\[1\], '\*', 'e', ARGV\[1\]/);
  assert.match(ENQUEUE_LUA, /return \{prior, orig\}/);
});

test('stream and dedupe names follow the wire namespace', () => {
  assert.equal(streamName('whatsapp', 'acct-1'), 'nq:in:whatsapp:acct-1');
  assert.equal(dedupeKey('v1:abc'), 'nq:dedupe:v1:abc');
  assert.equal(sourceKey('nq:in:whatsapp:acct-1', 'SK'),
    'nq:src:nq:in:whatsapp:acct-1:SK');
});

/**
 * A fake Redis honest enough to model the contract Lua's semantics and
 * record calls: KEYS = [stream, nq:src key, 'nq:dedupe:' prefix, dedupe key],
 * ARGV = [payload, event_id]; returns {stream_id, canonical_event_id}.
 */
function fakeRedis() {
  const store = new Map();
  const stream = [];
  const calls = [];
  function runLua(keys, args) {
    const src = keys[1];
    const dedupePfx = keys[2];
    const dedupeK = keys[3];
    const eventId = args[1];
    const orig = store.get(src);
    if (orig) {
      const prior = store.get(dedupePfx + orig);
      if (prior) return [prior, orig];
    }
    const prior = store.get(dedupeK);
    if (prior) { store.set(src, eventId); return [prior, eventId]; }
    const id = `1-${stream.length}`;
    stream.push({ id, fields: { e: args[0] } });
    store.set(dedupeK, id);
    store.set(src, eventId);
    return [id, eventId];
  }
  return {
    calls, store, stream,
    async evalSha(sha, { keys, arguments: args }) {
      calls.push(['evalSha', sha, keys]);
      return runLua(keys, args);
    },
    async eval(script, args) {
      calls.push(['eval', script === ENQUEUE_LUA]);
      return runLua(args.keys, args.arguments);
    },
  };
}

test('enqueue is dedupe-idempotent on event_id and single-field', async () => {
  const redis = fakeRedis();
  const producer = new StreamProducer(redis, 'nq:in:whatsapp:acct-1');
  const env = { event_id: 'v1:e1', source_key: 'SK1', body: 'x' };
  const first = await producer.enqueue(env);
  const second = await producer.enqueue(env);
  assert.deepEqual(first, second);
  assert.deepEqual(first, { streamId: '1-0', eventId: 'v1:e1' });
  assert.equal(redis.stream.length, 1);
  assert.deepEqual(redis.calls[0][2], [
    'nq:in:whatsapp:acct-1',
    'nq:src:nq:in:whatsapp:acct-1:SK1',
    'nq:dedupe:',
    'nq:dedupe:v1:e1',
  ]);
  const payload = JSON.parse(redis.stream[0].fields.e);
  assert.equal(payload.event_id, 'v1:e1');
});

test('a rotated alias re-capture returns the ORIGINAL event id, one stream entry', async () => {
  const redis = fakeRedis();
  const producer = new StreamProducer(redis, 'nq:in:whatsapp:acct-1');
  const a = { event_id: 'v1:e1', source_key: 'SK2', body: 'x' };
  const first = await producer.enqueue(a);
  assert.deepEqual(first, { streamId: '1-0', eventId: 'v1:e1' });
  // Same source_key, new key version → new alias. The src mapping must
  // resolve to the original: same stream id, canonical event id v1:e1, and
  // NO second XADD — the receipt owner binds v1:e1, not v2:e2.
  const b = { event_id: 'v2:e2', source_key: 'SK2', body: 'x' };
  const second = await producer.enqueue(b);
  assert.deepEqual(second, { streamId: '1-0', eventId: 'v1:e1' });
  assert.equal(redis.stream.length, 1);
  assert.equal(redis.store.get('nq:src:nq:in:whatsapp:acct-1:SK2'), 'v1:e1');
});

test('a distinct source key enqueues its own stream entry', async () => {
  const redis = fakeRedis();
  const producer = new StreamProducer(redis, 'nq:in:whatsapp:acct-1');
  await producer.enqueue({ event_id: 'v1:e1', source_key: 'SKA' });
  const other = await producer.enqueue({ event_id: 'v1:e9', source_key: 'SKB' });
  assert.deepEqual(other, { streamId: '1-1', eventId: 'v1:e9' });
  assert.equal(redis.stream.length, 2);
});

test('enqueue falls back to EVAL on NOSCRIPT', async () => {
  const redis = fakeRedis();
  let first = true;
  const orig = redis.evalSha;
  redis.evalSha = async (sha, args) => {
    if (first) { first = false; throw new Error('NOSCRIPT No matching script'); }
    return orig.call(redis, sha, args);
  };
  const producer = new StreamProducer(redis, 's');
  const res = await producer.enqueue({ event_id: 'v1:x', source_key: 'SK' });
  assert.deepEqual(res, { streamId: '1-0', eventId: 'v1:x' });
  // calls[0] is the EVAL fallback carrying the literal script.
  assert.equal(redis.calls[0][0], 'eval');
  assert.equal(redis.calls[0][1], true);
});

// -- journal contract -----------------------------------------------------------

function tmpDir() { return mkdtempSync(path.join(tmpdir(), 'journal-')); }

test('journal lines match the frozen <len> <crc32> <json> format', () => {
  const dir = tmpDir();
  try {
    const j = new Journal(path.join(dir, 'j.log'));
    j.append({ probe: true });
    const raw = readFileSync(j.path);
    // Vector: python zlib.crc32 of the payload bytes.
    assert.deepEqual(raw, Buffer.from('14 3139119017 {"probe":true}\n'));
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test('recover: two valid records, torn tail truncates, interior corruption refuses', () => {
  const dir = tmpDir();
  try {
    const file = path.join(dir, 'j.log');
    const j = new Journal(file);
    j.append({ a: 1 });
    j.append({ b: 2 });
    assert.equal(j.recover().length, 2);
    // Torn tail: unterminated garbage after valid records → prefix survives.
    appendFileSync(file, Buffer.from('99 1 {"partial'));
    assert.equal(j.recover().length, 2);
    // Interior corruption: bad line WITH valid data after it → refuse.
    appendFileSync(file, Buffer.from('garbage line nope\n'));
    j.append({ c: 3 });
    assert.throws(() => j.recover(), JournalError);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test('plan() phases: enqueue-pending, receipt-pending, settled — in order', () => {
  const j = new Journal('/nonexistent');
  const records = [
    { probe: true },
    { envelope: { event_id: 'v1:a' } },
    { enqueued: { event_id: 'v1:a', stream_id: '1-0', orig_event_id: 'v1:a' } },
    { envelope: { event_id: 'v1:b' }, react: { emoji: '👍' } },
    { enqueued: { event_id: 'v1:b', stream_id: '1-1', orig_event_id: 'v1:b' } },
    { envelope: { event_id: 'v1:c' }, react: { emoji: '👍' } },
    { ambiguous: { stanza_id: 'X' } },
    { envelope: { event_id: 'v1:d' }, react: { emoji: '👍' } },
    { enqueued: { event_id: 'v1:d', stream_id: '1-3', orig_event_id: 'v1:d' } },
    { receipted: { event_id: 'v1:d', action_id: 'v1:d:react:0', state: 'confirmed' } },
  ];
  const plan = j.plan(records);
  // v1:a enqueued (no react — done); v1:b receipt-pending; v1:c both pending;
  // v1:d fully settled; ambiguous retained out of the work list.
  assert.deepEqual(plan.work.map((w) => w.envelope.event_id), ['v1:b', 'v1:c']);
  assert.equal(plan.pendingEnqueues, 1);
  assert.equal(plan.pendingReceipts, 2);
  assert.equal(plan.work[0].enqueued.stream_id, '1-1');
  assert.equal(plan.work[1].enqueued, null);
});

test('compactable() keeps pending receipts and their markers, drops settled', () => {
  const j = new Journal('/nonexistent');
  const records = [
    { probe: true },
    { envelope: { event_id: 'v1:done' } },
    { enqueued: { event_id: 'v1:done', stream_id: '1-0', orig_event_id: 'v1:done' } },
    { envelope: { event_id: 'v1:pending' }, react: { emoji: '👍' } },
    { enqueued: { event_id: 'v1:pending', stream_id: '1-1', orig_event_id: 'v1:pending' } },
    { ambiguous: { stanza_id: 'X' } },
  ];
  const keep = j.compactable(records);
  const kinds = keep.map((r) => Object.keys(r)[0]);
  // The settled v1:done pair and the probe drop; the pending receipt keeps
  // its envelope AND its enqueued marker (orig alias owns the action).
  assert.deepEqual(kinds, ['envelope', 'enqueued', 'ambiguous']);
  assert.equal(keep[0].envelope.event_id, 'v1:pending');
  assert.equal(keep[1].enqueued.orig_event_id, 'v1:pending');
});

test('journal capacity refuses instead of dropping oldest', () => {
  const dir = tmpDir();
  try {
    const j = new Journal(path.join(dir, 'j.log'), { maxBytes: 80 });
    j.append({ probe: true });                    // 24 bytes
    j.append({ envelope: { event_id: 'v1:big' } }); // 46 → 70 total
    assert.throws(() => j.append({ more: 'data'.repeat(10) }), JournalError);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});
